---@class InspectHint
---@field targetPoint           UnityEngine.Transform     @ 生成Hint的世界坐标位置
---@field ui_hintPrefab         UnityEngine.RectTransform @ Hint的Prefab
---@field ui_hintPrefabInPC     UnityEngine.RectTransform @ Hint的Prefab pc 版
local InspectHint = Class('InspectHint')
-- 外部调用
-- local InspectHint = import('Game.DreamSpace.Hint.InspectHint')


-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')

local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')

local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')

local DreamSpaceCamera = import('Game.DreamSpace.Tools.DreamSpaceCamera')

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector2 = CS.UnityEngine.Vector2
local Vector3 = CS.UnityEngine.Vector3
local RaycastHit = CS.UnityEngine.RaycastHit


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool

local DreamSpaceUtils = CS.DreamSpace.DreamSpaceUtils
local LuaBehaviour = CS.Engine.Modules.LuaBehaviour
local LuaParameters = CS.Engine.Modules.LuaParameters
local GlobalsInDreamSpace = CS.DreamSpace.GlobalsInDreamSpace

local InteractableHintUtils = CS.InteractableHint.InteractableHintUtils

local BehaviorExecutedAfterCMBrain = CS.DreamSpace.BehaviorExecutedAfterCMBrain -- 指定了 execution order: 11



-- ========================================================


-- 3段动画:
local animationStr_showIn        = "ActionDreamlandHintPointNode_Probe"
local animationStr_showOff        = "ActionDreamlandHintPointNode_Data"
local animationStr_off_2_in      = "ActionDreamlandHintPointNode_Probe-Data"
local animationStr_in_2_off      = "ActionDreamlandHintPointNode_Data-Probe"


local raycastHits = CS.System.Array.CreateInstance( typeof(RaycastHit), 16 ) -- RaycastHit[], 16 个元素, 为避免GC而存在

local farPos = Vector3(0.0, 10000.0, 0.0)


local inn_wallTags = CS.System.Array.CreateInstance( typeof(CS.System.String), 3 ) -- todo: 未来搞出参数
inn_wallTags[0] = "Wall"
inn_wallTags[1] = "CanJump"
inn_wallTags[2] = "Wall"



-- =========================== 全体实例 =============================

-- 存储所有 inScreen 的实例:
local allInstances = {} -- map  [id,instance]

-- 找到第一个 有效实例, 或 nil;  -- todo: 可升级为: 找到离主角最近的一个 实例
function InspectHint._FindFirstInstance()
    for k,v in pairs(allInstances) do 
        if isNotNull(v) then 
            return v
        end 
    end 
    return nil
end


-- 每个 instance 分配一个 id:
local idCounter = 1 -- 
function InspectHint._GetId()
    idCounter = idCounter + 1
    return idCounter
end



function InspectHint.InitStatics()
    idCounter = 1
    allInstances = {}
end


-- ========================================================


function InspectHint:__init()
    self.isInScreen = false 
    self.isLastInScreen = false 
    self.WhenButtonPressed = nil -- 函数指针
    ---
    self.isInit = false;
end



function InspectHint:__delete()
    self.co_1 = nil
end




function InspectHint:Start()
    KTool.SetActive(self.controller.gameObject, true);

    -- ================== self ================:
    assert( self.targetPoint and self.ui_hintPrefab and self.ui_hintPrefabInPC )

    self.id = InspectHint._GetId()

    self.LateUpdateFunc = function()
        self:LateUpdate()
    end

    -- 让 c# 脚本 BehaviorExecutedAfterCMBrain 来运行 LateUpdate(), 以此克服 ui元素晃动的问题
    self.behaviorExecutedAfterCMBrain = KTool.GetComponent(self.controller.gameObject, typeof(BehaviorExecutedAfterCMBrain))
    self.behaviorExecutedAfterCMBrain:INTERNAL_LateUpdate( '+', self.LateUpdateFunc )

    -- must after Awake()
    self.mCamera = DreamSpaceCamera.GetMainCamera()

    self.luaParams = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( self.luaParams )


    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(self.DelayInit, self)
end



function InspectHint:DelayInit() 

    -- 读取参数:
    self.nearImageIdx = LuaParametersReader.Read( self.luaParams, "nearImageIdx", LuaParametersReader.Type.Int )
    self.circleRadius = LuaParametersReader.Read( self.luaParams, "circleRadius", LuaParametersReader.Type.Float ) -- 触发半径
    self.heightOffset = LuaParametersReader.Read( self.luaParams, "heightOffset", LuaParametersReader.Type.Float ) -- 0.03;  与 role pos 的 垂直高度差
    self.deadZoneWidth = LuaParametersReader.Read( self.luaParams, "deadZoneWidth", LuaParametersReader.Type.Float ) -- 10;  屏幕边缘的一圈死区的宽度; 单位为屏幕像素


    -- 先等待一帧, 等新场景中新的 SwitchablePlayer 实例被创建
    coroutine.yield(Yielders.EndOfFrame)

    ---
    local RoleControllerRootCanvasMgr = import('Game.DreamSpace.UI.RoleControllerRootCanvasMgr'):GetInstance()
    RoleControllerRootCanvasMgr:CheckOrInitSync()
    local parentUICanvas = RoleControllerRootCanvasMgr.dynamicsCanvas
    assert( parentUICanvas )

    -- ----- role ------:
    -- 只会查找 N 次, 还是找不到就放弃 hint 功能了;
    self.role = nil
    for i=0, DreamSpaceStates.DelayInitWaitFrames do 

        self.role = GlobalsInDreamSpace.FindComponent("vTargetFollow")
        if not isNull(self.role) then
            break
        end
        coroutine.yield(Yielders.EndOfFrame)
    end

    if isNull( self.role ) then
        printError( false, "始终没能找到 gamoebj: SwitchablePlayer/VTarget/Follow, 请查找原因" )
        return
    end

    -- build ui hint:
    local hintPrefab = nil
    local uiHintLuaStr = "Game.DreamSpace.Hint.GearHintUI"
    if DreamSpaceStates.isWindowsPlatform then
        hintPrefab = self.ui_hintPrefabInPC
    else
        hintPrefab = self.ui_hintPrefab
    end

    self.hintRTF = Object.Instantiate( hintPrefab, parentUICanvas.transform )
    self.hintRTF.name = "InspectHint_" .. tostring(self.id)


    self.inspectHintUI = DreamSpaceLuaUtils.GetLuaScr(self.hintRTF.gameObject, uiHintLuaStr )
    assert( self.inspectHintUI )

    if DreamSpaceStates.isWindowsPlatform == true then 
        self.inspectHintUI:SetPCKey( "R" )
    end 

    self.inspectHintUI:SetInteractable( false ) -- 阻止交互

    -- 选择近景 显示哪个图片:
    self.inspectHintUI:SetNearImage( self.nearImageIdx ) -- 4: 问号

    self.rootCanvasCoordinateMatrix = DreamSpaceUtils.RefreshRootCanvasCoordinateMatrix( self.hintRTF );

    -----:
    self.isInit = true

end



function InspectHint:OnDestroy()

    self.behaviorExecutedAfterCMBrain:INTERNAL_LateUpdate( '-', self.LateUpdateFunc )

    allInstances[self.id] = nil

    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --



function InspectHint:LateUpdate()

    if self.isInit == false then 
        return
    end 

    self.isInScreen, self.hintRTF.position = self:IsInScreen()

    if self.isInScreen ~= self.isLastInScreen then 
        self.isLastInScreen = self.isInScreen

        if self.isInScreen == true then 
            -- 显示
            self:Show()
            allInstances[self.id] = self

        else 
            -- 隐藏
            self:Hide()
            allInstances[self.id] = nil
        end
    end 
end



function InspectHint:Show()
    KTool.SetActive( self.hintRTF.gameObject, true )
    self.inspectHintUI:SetInteractable( true )
    --self.inspectHintUI.ui_hintAnimation:Play( animationStr_off_2_in )
    self.inspectHintUI.ui_hintAnimation:Play( animationStr_showOff )
end



function InspectHint:Hide()
    KTool.SetActive( self.hintRTF.gameObject, false )
    self.inspectHintUI:SetInteractable( false )
    self.inspectHintUI.ui_hintAnimation:Play( animationStr_in_2_off )
end




-- targetPoint 是否在相机视野内
-- ret: bool, pos
function InspectHint:IsInScreen()

    local distance = (self.role.position - self.targetPoint.position).magnitude
    if distance > self.circleRadius then 
        return false, farPos
    end 

    -- 若中间存在 有效遮挡, 则不显示:
    if InteractableHintUtils.IsHintBeBlocked( self.mCamera, self.targetPoint.position, raycastHits, inn_wallTags ) then 
        --print("koko 存在遮挡")
        return false, farPos
    end


    local isDirectionsOpposite = Vector3.Dot( self.mCamera.transform.forward, self.targetPoint.position - self.mCamera.transform.position ) < 0.0
    if isDirectionsOpposite == true then 
        --print("koko 后半球")
        return false, farPos
    end 

    -- Vector2
    local newAnchoredPosition = DreamSpaceUtils.CalculateAnchoredPosition( self.mCamera, self.targetPoint.position, self.heightOffset )


    local isInScreen = InteractableHintUtils.IsInScreen(newAnchoredPosition, self.deadZoneWidth)
    if isInScreen == false then 
        --print("koko 不在屏幕内")
        return false, farPos
    end 

    -- 准确计算 ui元素的 world-space 3d position:
    local pos = DreamSpaceUtils.AnchoredPosition_To_PosWS( newAnchoredPosition, self.rootCanvasCoordinateMatrix );

    return true, pos
end



---@param call_ UnityEngine.Events.UnityAction
function InspectHint:BindHintButton(  call_ )
    if self.isInit == false then
        return
    end
    self.inspectHintUI.ui_inScreenButton.onClick:AddListener( call_ )

    self.WhenButtonPressed = call_
end



-- static
-- pc模式时, 按下解谜按键后调用
function InspectHint.TriggerInspectInPCMode()

    local currentActiveInspectHint = InspectHint._FindFirstInstance()

    if currentActiveInspectHint ~= nil then 
        assert( currentActiveInspectHint.WhenButtonPressed ~= nil )
        currentActiveInspectHint.WhenButtonPressed()
    end
end 



return InspectHint
